-- Migration 20260918084302_add_team_member_description was generated by
-- `prisma migrate dev`, which diffed the schema and dropped the
-- (modelId, variant, yearFrom, yearTo) NULLS NOT DISTINCT unique index —
-- it's migration-SQL-only (see 20260908130000), invisible to the Prisma
-- schema. Without it, prisma/seed-catalog.ts's skipDuplicates had nothing
-- to conflict on and re-running it duplicated the whole catalog.
-- Merge the duplicates (keep the oldest row of each group, repoint what
-- references the others), then restore the index.

CREATE TEMP TABLE "catalog_dupes" AS
SELECT "id", MIN("id") OVER (PARTITION BY "modelId", "variant", "yearFrom", "yearTo") AS "keepId"
FROM "dbo"."VehicleCatalog";
DELETE FROM "catalog_dupes" WHERE "id" = "keepId";

UPDATE "dbo"."VehicleListing" t SET "vehicleCatalogId" = d."keepId"
FROM "catalog_dupes" d WHERE t."vehicleCatalogId" = d."id";

UPDATE "dbo"."GarageVehicle" t SET "vehicleCatalogId" = d."keepId"
FROM "catalog_dupes" d WHERE t."vehicleCatalogId" = d."id";

-- Repointing must not collide on (productId, vehicleCatalogId): a product
-- may already be fitted to the kept row, or to two or more copies of it
-- (3+ copies when the seed ran 3+ times). Keep one fitment per product per
-- target row — the one already on the kept row if any, else the oldest —
-- and drop the rest.
DELETE FROM "dbo"."ProductFitment" f
USING (
  SELECT pf."id",
    ROW_NUMBER() OVER (
      PARTITION BY pf."productId", COALESCE(d."keepId", pf."vehicleCatalogId")
      ORDER BY (d."id" IS NOT NULL), pf."id"
    ) AS "rn"
  FROM "dbo"."ProductFitment" pf
  LEFT JOIN "catalog_dupes" d ON d."id" = pf."vehicleCatalogId"
) ranked
WHERE f."id" = ranked."id" AND ranked."rn" > 1;
UPDATE "dbo"."ProductFitment" t SET "vehicleCatalogId" = d."keepId"
FROM "catalog_dupes" d WHERE t."vehicleCatalogId" = d."id";

-- Kept rows carry the garage count of the merged ones.
UPDATE "dbo"."VehicleCatalog" c SET "popularity" = (
  SELECT COUNT(*) FROM "dbo"."GarageVehicle" g WHERE g."vehicleCatalogId" = c."id"
)
WHERE c."id" IN (SELECT DISTINCT "keepId" FROM "catalog_dupes");

DELETE FROM "dbo"."VehicleCatalog" WHERE "id" IN (SELECT "id" FROM "catalog_dupes");
DROP TABLE "catalog_dupes";

CREATE UNIQUE INDEX "VehicleCatalog_modelId_variant_yearFrom_yearTo_key"
  ON "dbo"."VehicleCatalog" ("modelId", "variant", "yearFrom", "yearTo")
  NULLS NOT DISTINCT;
